// OpenWrt – Gerenciador de pacotes.
//
// OpenWrt 24.10 e anteriores usam `opkg`; 25.x em diante usam `apk`. A versão
// decide (firmware lido pelo `detect`); sem versão numérica (SNAPSHOT, nunca
// detectado), vale o binário que existir no roteador.

// Gerenciador para um firmware conhecido; `()` quando a versão não decide.
fn manager_for_release(firmware) {
    if firmware == () { return (); }
    let major = regex_capture(firmware, "^(\\d+)\\.");
    if major == () { return (); }
    if parse_int(major) >= 25 { "apk" } else { "opkg" }
}

fn manager_from(device, firmware) {
    let by_release = manager_for_release(firmware);
    if by_release != () { return by_release; }
    let found = device.ssh("command -v apk >/dev/null 2>&1 && echo apk || echo opkg");
    if trimmed(found.stdout) == "apk" { "apk" } else { "opkg" }
}

fn manager(device) {
    manager_from(device, device.info.firmware)
}

// `busybox-1.36.1-r2` → [nome, versão] (formato do apk).
fn split_apk(token) {
    let name = regex_capture(token, "^(.+)-[^-]+-r\\d+$");
    if name == () { name = regex_capture(token, "^(.+?)-\\d"); }
    if name == () { return [token, ""]; }
    [name, token.sub_string(name.len() + 1)]
}

// Pacotes instalados: nome → versão.
fn installed_map(device, mgr) {
    let found = #{};
    if mgr == "apk" {
        for line in lines(device.run("apk list --installed")) {
            let parts = split_apk(words(line)[0]);
            found[parts[0]] = parts[1];
        }
    } else {
        for line in lines(device.run("opkg list-installed")) {
            let parts = line.split(" - ");
            if parts.len() >= 2 { found[parts[0]] = parts[1]; }
        }
    }
    found
}

fn row(name, version, description, installed) {
    #{ name: name, version: version, description: description, installed: installed }
}

// Roda e devolve o que o roteador respondeu, com o comando na frente.
fn shown(device, command) {
    let r = device.ssh(command);
    let text = "$ " + command + "\n" + r.stdout;
    if trimmed(r.stderr) != "" { text += "\n" + r.stderr; }
    #{ text: text, exit: r.exit }
}

fn detect(device, params) {
    let release = parse_kv(device.run("cat /etc/openwrt_release"), "=");
    let board = device.ssh("ubus call system board");
    let model = ();
    if board.exit == 0 { model = json_parse(board.stdout).model; }
    let firmware = release.DISTRIB_RELEASE;
    #{
        firmware: firmware,
        target: release.DISTRIB_TARGET,
        description: release.DISTRIB_DESCRIPTION,
        model: model,
        package_manager: manager_from(device, firmware)
    }
}

fn list_packages(device, params) {
    let mgr = manager(device);
    let installed = installed_map(device, mgr);
    let query = params.query;
    let rows = [];
    if query == () || trimmed(query) == "" {
        for name in installed.keys() {
            rows.push(row(name, installed[name], "", true));
        }
        return rows;
    }
    let filter = " | grep -i -- " + shell_quote(query) + " | head -n 200";
    if mgr == "apk" {
        for line in lines(device.run("apk list" + filter)) {
            let parts = split_apk(words(line)[0]);
            rows.push(row(parts[0], parts[1], "", installed.contains(parts[0])));
        }
    } else {
        for line in lines(device.run("opkg list" + filter)) {
            let parts = line.split(" - ");
            let description = if parts.len() >= 3 { parts[2] } else { "" };
            let version = if parts.len() >= 2 { parts[1] } else { "" };
            rows.push(row(parts[0], version, description, installed.contains(parts[0])));
        }
    }
    rows
}

// Prazos dos comandos que baixam do repositório: o índice num roteador lento
// ou num link ruim passa fácil dos 30 s do `device.ssh`.
fn update_timeout() { 180000 }
fn install_timeout() { 240000 }
fn mirror_timeout() { 300000 }

// Mensagem de um erro pego por `catch` (texto do `throw` ou erro do sistema).
fn error_text(err) {
    if type_of(err) == "map" && err.message != () { err.message } else { err.to_string() }
}

// Como `shown`, com prazo próprio. O prazo estourado vira resultado (`exit`
// -1, `timeout`) em vez de derrubar a ação: quem chama escolhe a frase. O
// cancelamento pelo operador continua derrubando.
fn shown_live(device, command, timeout_ms) {
    let r = ();
    try {
        r = device.ssh_live(command, #{ timeout_ms: timeout_ms });
    } catch (err) {
        let message = error_text(err);
        if message.contains("cancelada") { throw message; }
        return #{ text: "$ " + command + "\n" + message, exit: -1, timeout: true };
    }
    let text = "$ " + command + "\n" + r.stdout;
    if trimmed(r.stderr) != "" { text += "\n" + r.stderr; }
    #{ text: text, exit: r.exit, timeout: false }
}

fn add_command(mgr, name) {
    if mgr == "apk" { "apk add " + name } else { "opkg install " + name }
}

// Os índices dos repositórios configurados, um por linha.
fn repo_index_cmd(mgr) {
    if mgr == "apk" {
        "cat /etc/apk/repositories.d/*.list /etc/apk/repositories 2>/dev/null | grep -E '^https?://'"
    } else {
        "cat /etc/opkg/distfeeds.conf /etc/opkg/customfeeds.conf 2>/dev/null | grep -E '^src' | awk '{ print $3 \"/Packages.gz\" }'"
    }
}

// O roteador baixa direto do repositório? Confere o DNS e um índice (10 s
// cada) antes de instalar: com o DNS quebrado, o gerenciador esperaria
// repositório por repositório e a instalação estouraria o prazo.
fn reach_repository(device, mgr) {
    let command = "u=$(" + repo_index_cmd(mgr) + " | head -n 1); [ -n \"$u\" ] || { echo sem-repositorio; exit 2; }; h=${u#*://}; h=${h%%/*}; nslookup \"$h\" >/dev/null 2>&1 || { echo \"dns $h\"; exit 3; }; wget -q -T 10 --spider \"$u\" 2>&1 || { echo \"falhou $u\"; exit 4; }; echo ok";
    let r = shown_live(device, command, 60000);
    let reason = if r.exit == 0 { "ok" } else if r.exit == 2 { "none" } else if r.exit == 3 { "dns" } else if r.exit == 4 && tls_failure(r.text) { "tls" } else { "net" };
    #{ reason: reason, text: r.text }
}

// Por que o roteador não baixou direto, numa frase.
fn reach_reason(device, reach) {
    if reach.reason == "dns" {
        let host = regex_capture(reach.text, "(?m)^dns (\\S+)");
        if host == () { host = "o repositório"; }
        return "o roteador não resolve nomes: o DNS que ele mesmo usa (/etc/resolv.conf) não respondeu para " + host;
    }
    if reach.reason == "tls" {
        return "o roteador não validou o HTTPS do repositório (o relógio dele marca " + trimmed(device.run("date")) + ")";
    }
    "o roteador não alcançou o repositório (sem saída para a internet?)"
}

fn reach_fix(reach) {
    if reach.reason == "dns" { return "Corrija o DNS do próprio roteador"; }
    if reach.reason == "tls" { return "Acerte o NTP do roteador"; }
    "Confira a saída do roteador para a internet"
}

// Instala pelo espelho da central (`device.package_mirror()`): os
// repositórios oficiais apontando para ela, num arquivo de /tmp (RAM) apagado
// no fim — a configuração do roteador não muda. O endereço é o da central
// vista pelo roteador ($SSH_CLIENT). O gerenciador continua conferindo a
// assinatura do OpenWrt no índice e em cada pacote. Saída 5: o roteador não
// alcança a central; 2: nenhum repositório oficial para espelhar.
fn mirror_command(mgr, mirror, name) {
    let head = "ip=${SSH_CLIENT%% *}; case \"$ip\" in *:*) ip=\"[$ip]\";; esac; b=http://$ip:" + mirror.port + mirror.path + "; ";
    let rewrite = "sed -E \"s#https?://downloads\\.openwrt\\.org#$b#\"";
    if mgr == "apk" {
        return head + "L=/tmp/nm-mirror.list; " + repo_index_cmd(mgr) + " | grep -F '://downloads.openwrt.org/' | " + rewrite + " > $L; [ -s $L ] || { echo sem-repositorio-oficial; rm -f $L; exit 2; }; wget -q -T 10 --spider \"$(head -n 1 $L)\" 2>&1 || { echo \"central-inalcancavel $b\"; rm -f $L; exit 5; }; apk --repositories-file $L add " + name + "; s=$?; rm -f $L; exit $s";
    }
    head + "C=/tmp/nm-mirror-opkg.conf; grep -v '^src' /etc/opkg.conf > $C; cat /etc/opkg/distfeeds.conf /etc/opkg/customfeeds.conf 2>/dev/null | grep -E '^src' | grep -F '://downloads.openwrt.org/' | sed -E 's#^(src[^ ]*) +#\\1 nm_#' | " + rewrite + " >> $C; grep -q '^src' $C || { echo sem-repositorio-oficial; rm -f $C; exit 2; }; u=$(grep -m 1 '^src' $C | awk '{ print $3 \"/Packages.gz\" }'); wget -q -T 10 --spider \"$u\" 2>&1 || { echo \"central-inalcancavel $b\"; rm -f $C; exit 5; }; opkg -f $C update; opkg -f $C install " + name + "; s=$?; rm -f $C /var/opkg-lists/nm_*; exit $s"
}

// O pacote apareceu como instalado? O aviso, quando houver, vira o último
// parágrafo "Atenção: …" — quem usa esta ação (o teste de enlace) o mostra
// ao operador.
fn confirmed(device, mgr, pkg, text, warning) {
    if !installed_map(device, mgr).contains(pkg) {
        throw "O gerenciador terminou sem o pacote " + pkg + " aparecer como instalado. A saída completa está em \"Ver execução\".";
    }
    if warning == () { text } else { text + "\n\nAtenção: " + warning }
}

fn update_index(device, params) {
    let mgr = manager(device);
    let result = shown_live(device, mgr + " update", update_timeout());
    if result.timeout {
        throw "O roteador não terminou de baixar a lista de pacotes em " + update_timeout() / 60000 + " minutos (link lento ou repositório inalcançável).";
    }
    if result.exit != 0 { throw result.text; }
    result.text
}

// Falha de HTTPS ao baixar do repositório: quase sempre o relógio do
// roteador fora da hora (o certificado parece "ainda não válido") ou CA.
fn tls_failure(text) {
    text.contains("verify error") || text.contains("certificate") || text.contains("CERT")
}

// O motivo numa frase — a saída inteira do gerenciador continua no
// registro da execução ("Ver execução").
fn install_failure(device, mgr, name, text, timed_out) {
    if text.contains("Could not lock") || text.contains("Unable to lock") {
        return "Outro gerenciador de pacotes está rodando no roteador (talvez uma instalação anterior que ainda não terminou). Espere um minuto e tente de novo.";
    }
    if timed_out {
        return "O roteador não terminou a instalação de " + name + " no prazo (link lento ou roteador sobrecarregado). Ela pode continuar rodando nele: espere um pouco e tente de novo — se o pacote já tiver entrado, nada é refeito.";
    }
    if tls_failure(text) {
        let clock = trimmed(device.run("date"));
        return "O roteador não validou o certificado HTTPS do repositório de pacotes. O relógio dele marca " + clock + " — com a data errada, o certificado parece ainda não valer. Acerte o NTP do roteador e tente de novo.";
    }
    if text.contains("No space left") {
        return "Falta espaço na flash do roteador para instalar " + name + ".";
    }
    if text.contains("unable to select") || text.contains("Unknown package") || text.contains("not found") {
        return "O pacote " + name + " não existe nos repositórios configurados neste roteador.";
    }
    if text.contains("resolve") || text.contains("temporary error") || text.contains("Network unreachable") || text.contains("Connection refused") || text.contains("timed out") {
        return "O roteador não alcançou o repositório de pacotes (sem internet ou sem DNS). Confira a saída dele para a internet.";
    }
    "O gerenciador de pacotes (" + mgr + ") não conseguiu instalar " + name + ". A saída completa está em \"Ver execução\"."
}

fn install_package(device, params) {
    let mgr = manager(device);
    let name = shell_quote(params.name);
    if installed_map(device, mgr).contains(params.name) {
        return "O pacote " + params.name + " já está instalado. Nada foi alterado.";
    }
    let reach = reach_repository(device, mgr);
    if reach.reason == "none" {
        throw "O roteador não tem nenhum repositório de pacotes configurado.";
    }
    if reach.reason == "ok" {
        let update = shown_live(device, mgr + " update", update_timeout());
        let install = shown_live(device, add_command(mgr, name), install_timeout());
        let text = reach.text + "\n" + update.text + "\n" + install.text;
        if install.exit != 0 { throw install_failure(device, mgr, params.name, text, install.timeout); }
        return confirmed(device, mgr, params.name, text, ());
    }

    // O roteador não baixa direto: pela central, que tem DNS, relógio e
    // saída para a internet.
    let why = reach_reason(device, reach);
    let text = reach.text;
    let central = "";
    let mirror = device.package_mirror();
    if mirror == () {
        central = " A central não pode servir os pacotes a este equipamento (ele é alcançado por um agente remoto).";
    } else {
        let via = shown_live(device, mirror_command(mgr, mirror, name), mirror_timeout());
        text += "\n" + via.text;
        if via.exit == 0 {
            return confirmed(device, mgr, params.name, text, "Instalado pela central (espelho de pacotes), porque " + why + ". Os pacotes foram conferidos pela assinatura do OpenWrt. " + reach_fix(reach) + " para ele voltar a instalar sozinho.");
        }
        if via.exit == 5 {
            let address = regex_capture(via.text, "(?m)^central-inalcancavel (\\S+)");
            if address == () { address = "a central"; }
            central = " Pela central também não deu: o roteador não alcançou " + address + " (firewall entre o roteador e a central, ou a porta da API não publicada).";
        } else if via.exit != 2 {
            // Chegou ao gerenciador: pacote inexistente, espaço, trava ou
            // prazo — o motivo dele vale mais que o do caminho.
            throw install_failure(device, mgr, params.name, via.text, via.timeout);
        }
    }

    // Último recurso para o HTTPS recusado: o espelho HTTP do próprio
    // repositório, com a lista em /tmp apagada no fim.
    if mgr == "apk" && reach.reason == "tls" {
        let list = "/tmp/nm-repos-http.list";
        let retry = shown_live(device, "cat /etc/apk/repositories.d/*.list /etc/apk/repositories 2>/dev/null | grep '^https://' | sed 's#^https://#http://#' > " + list + " && apk --repositories-file " + list + " add " + name + "; status=$?; rm -f " + list + "; exit $status", install_timeout());
        text += "\n" + retry.text;
        if retry.exit == 0 {
            return confirmed(device, mgr, params.name, text, "Instalado pelo espelho HTTP do repositório, porque " + why + ". Os pacotes foram conferidos pela assinatura do OpenWrt. Recomendo acertar o NTP do roteador.");
        }
    }
    throw "Não deu para baixar o " + params.name + ": " + why + "." + central + " " + reach_fix(reach) + " e tente de novo.";
}

fn remove_package(device, params) {
    let mgr = manager(device);
    if !installed_map(device, mgr).contains(params.name) {
        return "O pacote " + params.name + " não está instalado. Nada foi alterado.";
    }
    let name = shell_quote(params.name);
    let command = if mgr == "apk" { "apk del " + name } else { "opkg remove " + name };
    let result = shown(device, command);
    if result.exit != 0 { throw result.text; }
    result.text
}
